-- Change presentation only; keep products, menu destinations, images and editorial content.
UPDATE site_settings SET body=json_set(body,'$.design','editorial','$.shop.presentation','editorial','$.shop.layout','list','$.shop.columns',1,'$.shop.tabletColumns',1,'$.shop.mobileColumns',1),version=version+1 WHERE id='appearance' AND (COALESCE(json_extract(body,'$.design'),'')<>'editorial' OR COALESCE(json_extract(body,'$.shop.presentation'),'')<>'editorial');
--> statement-breakpoint
UPDATE puck_pages SET published=CASE WHEN published IS NULL OR instr(published,'editorial-introduction')>0 THEN published ELSE json_set(published,'$.content',json((SELECT json_group_array(json(value)) FROM (
 SELECT '{"type":"Texte","props":{"id":"editorial-introduction","title":"Au Parrain Généreux","body":"La plus ancienne chocolaterie du Havre depuis 1890.","level":"h1","style":{"background":"","color":"","padding":64,"paddingX":28,"margin":0,"radius":0,"maxWidth":1200,"align":"center","font":"inherit","size":18,"gap":24,"width":100,"minHeight":0,"visualHeight":0,"visualBackground":""}}}' AS value,-1 AS position
 UNION ALL
 SELECT CASE WHEN json_extract(block.value,'$.type')='Liens' THEN json_set(block.value,'$.props.items',json((SELECT json_group_array(json(value)) FROM (
 SELECT json_set(link.value,'$.image',CASE WHEN COALESCE(json_extract(link.value,'$.image'),'')<>'' THEN json_extract(link.value,'$.image') WHEN json_extract(link.value,'$.href') IN ('/bonbons','/maison#nos-recettes','/boutique') THEN '/images/bonbons-editorial-deep.webp' WHEN json_extract(link.value,'$.href')='/#nous-trouver' THEN '/images/plan-boutique-le-havre-v4-transparent.png' ELSE '/images/boutique-historique.jpeg' END,'$.alt',COALESCE(json_extract(link.value,'$.alt'),json_extract(link.value,'$.label'))) AS value FROM json_each(block.value,'$.props.items') link ORDER BY CAST(link.key AS INTEGER)
 )))) WHEN json_extract(block.value,'$.type')='Texte' AND json_extract(block.value,'$.props.level')='h1' THEN json_set(block.value,'$.props.level','h2') ELSE block.value END AS value,CAST(block.key AS INTEGER) AS position
 FROM json_each(published,'$.content') block ORDER BY position
)))) END,draft=CASE WHEN draft IS NULL OR instr(draft,'editorial-introduction')>0 THEN draft ELSE json_set(draft,'$.content',json((SELECT json_group_array(json(value)) FROM (
 SELECT '{"type":"Texte","props":{"id":"editorial-introduction","title":"Au Parrain Généreux","body":"La plus ancienne chocolaterie du Havre depuis 1890.","level":"h1","style":{"background":"","color":"","padding":64,"paddingX":28,"margin":0,"radius":0,"maxWidth":1200,"align":"center","font":"inherit","size":18,"gap":24,"width":100,"minHeight":0,"visualHeight":0,"visualBackground":""}}}' AS value,-1 AS position
 UNION ALL
 SELECT CASE WHEN json_extract(block.value,'$.type')='Liens' THEN json_set(block.value,'$.props.items',json((SELECT json_group_array(json(value)) FROM (
 SELECT json_set(link.value,'$.image',CASE WHEN COALESCE(json_extract(link.value,'$.image'),'')<>'' THEN json_extract(link.value,'$.image') WHEN json_extract(link.value,'$.href') IN ('/bonbons','/maison#nos-recettes','/boutique') THEN '/images/bonbons-editorial-deep.webp' WHEN json_extract(link.value,'$.href')='/#nous-trouver' THEN '/images/plan-boutique-le-havre-v4-transparent.png' ELSE '/images/boutique-historique.jpeg' END,'$.alt',COALESCE(json_extract(link.value,'$.alt'),json_extract(link.value,'$.label'))) AS value FROM json_each(block.value,'$.props.items') link ORDER BY CAST(link.key AS INTEGER)
 )))) WHEN json_extract(block.value,'$.type')='Texte' AND json_extract(block.value,'$.props.level')='h1' THEN json_set(block.value,'$.props.level','h2') ELSE block.value END AS value,CAST(block.key AS INTEGER) AS position
 FROM json_each(draft,'$.content') block ORDER BY position
)))) END,version=version+1 WHERE path='/' AND ((published IS NOT NULL AND instr(published,'editorial-introduction')=0) OR (draft IS NOT NULL AND instr(draft,'editorial-introduction')=0));
